+	if err := form.RunWithContext(ctx); err != nil {
+		if cancelErr := handleFormCancellation(outW, "Configure", err); cancelErr != nil {
+			return nil, cancelErr
+		}
+		return nil, NewSilentError(errors.New("configure cancelled"))
